{
  "application": "ppt-generation",
  "case_id": "case-owid-mental-health",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 8,
    "audience": "public health policy analysts and mental health program planners",
    "tone": "data-forward, accessible, evidence-based"
  },
  "brief": {
    "title": "The Global Burden of Mental Illness: Prevalence, Impact, and the Treatment Gap",
    "one_liner": "A data-driven overview of global mental health conditions, their disease burden, and the persistent gap between need and treatment.",
    "goal": "Equip policy analysts with a clear understanding of which mental illnesses carry the greatest burden, how prevalent they are, and why closing the treatment gap should be a priority."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "The Global Burden of Mental Illness: Prevalence, Impact, and the Treatment Gap",
      "objective": "Cover slide with deck title, subtitle summarizing the scope (global data, 2023), and source attribution to Our World in Data / IHME."
    },
    {
      "id": "mental-health-scale",
      "title": "Hundreds of Millions Affected: 1 in 3 Women and 1 in 5 Men Face Major Depression",
      "objective": "Set the scene with key prevalence statistics. Use large callout numbers (1 in 3, 1 in 5) and a brief text block explaining that mental health conditions span from common (depression, anxiety) to less common but severe (schizophrenia, bipolar). Establish why this matters for policy."
    },
    {
      "id": "burden-by-category",
      "title": "Depression and Anxiety Dominate: ~695 and ~687 DALYs per 100K Respectively",
      "objective": "Horizontal bar chart showing DALYs per 100,000 people for each mental illness category (depressive disorders 694.6, anxiety disorders 686.5, schizophrenia 210.2, bipolar disorder 94.6, eating disorders 47.5). Reference figure_1. This is the central data slide."
    },
    {
      "id": "depression-vs-anxiety-parity",
      "title": "Depression and Anxiety Carry Nearly Equal Disease Burden Worldwide",
      "objective": "Highlight the near-parity between depressive and anxiety disorders in DALYs. Use a side-by-side comparison or paired bar visual. Note that together they account for the vast majority of mental health burden, dwarfing other categories."
    },
    {
      "id": "severe-conditions-lower-prevalence",
      "title": "Schizophrenia and Bipolar Disorder: Lower Prevalence but Severe Individual Impact",
      "objective": "Contrast the DALY figures for schizophrenia (210.2) and bipolar disorder (94.6) against depression/anxiety. Use a proportional visual or stacked chart. Emphasize that while population-level burden is lower, individual severity and disability are high."
    },
    {
      "id": "treatment-gap",
      "title": "Treatment Is Available but Often Lacking or Poor Quality",
      "objective": "Text-driven slide with supporting icons or a simple infographic. Convey that mental illnesses are treatable, yet many people do not receive adequate care. Mention stigma and discomfort sharing symptoms as barriers. Reference the difficulty in estimating true prevalence due to underreporting."
    },
    {
      "id": "coping-and-response",
      "title": "How People Cope: From Medication to Faith to Family Conversations",
      "objective": "Present the variety of coping strategies identified in global surveys — prescribed medication, religious/spiritual activities, talking to friends or family. Use an icon grid or categorized list. Reference figure_2 if applicable. Show that responses vary widely across countries."
    },
    {
      "id": "takeaways-and-implications",
      "title": "Key Takeaways: Prioritizing Depression, Anxiety, and Closing the Treatment Gap",
      "objective": "Summary slide with 4-5 bullet points: (1) Depression and anxiety together represent the overwhelming majority of mental health DALYs; (2) Schizophrenia and bipolar carry disproportionate individual burden; (3) Treatment exists but access and quality remain inadequate; (4) Stigma suppresses both help-seeking and accurate data; (5) Policy should prioritize scaling evidence-based interventions for common mental disorders while maintaining specialized care for severe conditions."
    }
  ]
}

