const pptxgen = require('pptxgenjs');

// Set up presentation
const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';

// Define Theme matching the "data-forward, accessible, evidence-based" tone
const theme = {
  primary: "1B3B6F",   // Dark Blue
  secondary: "065A82", // Medium Blue
  accent: "E57A44",    // Accent Coral/Orange for data callouts
  light: "98C1D9",     // Light Blue/Gray
  bg: "F8F9FA"         // Background off-white
};

// Helper function to add a title line
function addSlideTitle(slide, titleText) {
  slide.addText(titleText, {
    x: 0.5, y: 0.3, w: 9.0, h: 0.8,
    fontSize: 26, fontFace: "Arial",
    color: theme.primary, bold: true, valign: "middle"
  });

  slide.addShape(pres.shapes.LINE, {
    x: 0.5, y: 1.1, w: 9.0, h: 0,
    line: { color: theme.secondary, width: 2 }
  });
}

// Helper function to add page number badge
function addBadge(slide, number) {
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fill: { color: theme.accent },
    rectRadius: 0.15
  });
  slide.addText(number.toString().padStart(2, '0'), {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });
}

// ---------------------------------------------------------
// Slide 1: Cover Page
// ---------------------------------------------------------
const s1 = pres.addSlide();
s1.background = { color: theme.primary };

s1.addText("The Global Burden of Mental Illness", {
  x: 0.5, y: 1.8, w: 9.0, h: 1.0,
  fontSize: 44, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center"
});
s1.addText("Prevalence, Impact, and the Treatment Gap", {
  x: 0.5, y: 2.8, w: 9.0, h: 0.6,
  fontSize: 28, fontFace: "Arial", color: theme.light, align: "center"
});
s1.addText("Global Data (2023) • Source: Our World in Data / IHME", {
  x: 0.5, y: 4.5, w: 9.0, h: 0.5,
  fontSize: 16, fontFace: "Arial", color: "FFFFFF", align: "center"
});

// ---------------------------------------------------------
// Slide 2: Prevalence
// ---------------------------------------------------------
const s2 = pres.addSlide();
s2.background = { color: theme.bg };
addSlideTitle(s2, "Hundreds of Millions Affected: 1 in 3 Women and 1 in 5 Men Face Major Depression");

s2.addText("1 in 3", {
  x: 1.0, y: 1.6, w: 3.5, h: 1.5,
  fontSize: 72, fontFace: "Arial", color: theme.secondary, bold: true, align: "center"
});
s2.addText("Women experience major\ndepression in their lifetime", {
  x: 1.0, y: 3.2, w: 3.5, h: 0.8,
  fontSize: 18, fontFace: "Arial", color: theme.primary, align: "center"
});

s2.addText("1 in 5", {
  x: 5.5, y: 1.6, w: 3.5, h: 1.5,
  fontSize: 72, fontFace: "Arial", color: theme.accent, bold: true, align: "center"
});
s2.addText("Men experience major\ndepression in their lifetime", {
  x: 5.5, y: 3.2, w: 3.5, h: 0.8,
  fontSize: 18, fontFace: "Arial", color: theme.primary, align: "center"
});

s2.addText("Mental health conditions span from common (depression, anxiety) to less common but severe (schizophrenia, bipolar). Establishing prevalence is critical for policy.", {
  x: 0.5, y: 4.3, w: 9.0, h: 0.8,
  fontSize: 16, fontFace: "Arial", color: theme.primary, align: "center", bold: true, fill: { color: theme.light }
});
addBadge(s2, 2);

// ---------------------------------------------------------
// Slide 3: Burden by Category (Horizontal Bar Chart)
// ---------------------------------------------------------
const s3 = pres.addSlide();
s3.background = { color: theme.bg };
addSlideTitle(s3, "Depression and Anxiety Dominate: ~695 and ~687 DALYs per 100K");

s3.addChart(pres.charts.BAR, [
  {
    name: "DALYs per 100,000",
    labels: ["Eating disorders", "Bipolar disorder", "Schizophrenia", "Anxiety disorders", "Depressive disorders"],
    values: [47.5, 94.6, 210.2, 686.5, 694.6]
  }
], {
  x: 0.5, y: 1.3, w: 9.0, h: 3.6,
  barDir: "bar",
  chartColors: [theme.secondary],
  showValue: true,
  valAxisMaxVal: 800,
  catAxisLabelFontSize: 14,
  valAxisLabelFontSize: 14,
  dataLabelFontSize: 12,
  dataLabelColor: theme.primary
});
addBadge(s3, 3);

// ---------------------------------------------------------
// Slide 4: Parity (Side-by-side / Column Visual)
// ---------------------------------------------------------
const s4 = pres.addSlide();
s4.background = { color: theme.bg };
addSlideTitle(s4, "Depression and Anxiety Carry Nearly Equal Disease Burden Worldwide");

s4.addChart(pres.charts.BAR, [
  {
    name: "Depressive disorders",
    labels: ["Global Burden (DALYs)"],
    values: [694.6]
  },
  {
    name: "Anxiety disorders",
    labels: ["Global Burden (DALYs)"],
    values: [686.5]
  }
], {
  x: 0.5, y: 1.5, w: 5.0, h: 3.2,
  barDir: "col",
  chartColors: [theme.secondary, theme.accent],
  showLegend: true,
  legendPos: "b",
  showValue: true,
  dataLabelFontSize: 14,
  valAxisMaxVal: 800
});

const s4BulletPoints = [
  { text: "Depressive disorders and anxiety disorders together dominate the global mental health burden." },
  { text: "\n\nCombined, they account for roughly 80% of the total mental health disease burden across these five major categories." },
  { text: "\n\nThe near-parity in their DALY rates (~695 and ~687) highlights the massive dual challenge these common conditions present for public health frameworks worldwide." }
];

s4.addText(s4BulletPoints, {
  x: 6.0, y: 1.5, w: 3.5, h: 3.2,
  fontSize: 16, fontFace: "Arial", color: theme.primary, bullet: true, valign: "top"
});
addBadge(s4, 4);

// ---------------------------------------------------------
// Slide 5: Severe Conditions
// ---------------------------------------------------------
const s5 = pres.addSlide();
s5.background = { color: theme.bg };
addSlideTitle(s5, "Schizophrenia and Bipolar Disorder: Lower Prevalence but Severe Impact");

s5.addText("While affecting fewer people overall, severe mental illnesses carry a disproportionately high individual burden relative to their prevalence.", {
  x: 0.5, y: 1.3, w: 9.0, h: 0.6,
  fontSize: 18, fontFace: "Arial", color: theme.primary, bold: true
});

s5.addShape(pres.shapes.RECTANGLE, {
  x: 1.0, y: 2.2, w: 3.5, h: 2.2,
  fill: { color: theme.light }
});
s5.addText("Schizophrenia", {
  x: 1.0, y: 2.4, w: 3.5, h: 0.5,
  fontSize: 22, fontFace: "Arial", color: theme.primary, bold: true, align: "center"
});
s5.addText("210.2\nDALYs per 100k", {
  x: 1.0, y: 3.0, w: 3.5, h: 1.0,
  fontSize: 28, fontFace: "Arial", color: theme.accent, bold: true, align: "center"
});

s5.addShape(pres.shapes.RECTANGLE, {
  x: 5.5, y: 2.2, w: 3.5, h: 2.2,
  fill: { color: theme.light }
});
s5.addText("Bipolar Disorder", {
  x: 5.5, y: 2.4, w: 3.5, h: 0.5,
  fontSize: 22, fontFace: "Arial", color: theme.primary, bold: true, align: "center"
});
s5.addText("94.6\nDALYs per 100k", {
  x: 5.5, y: 3.0, w: 3.5, h: 1.0,
  fontSize: 28, fontFace: "Arial", color: theme.secondary, bold: true, align: "center"
});

s5.addText("The severity and disability associated with these conditions necessitate specialized, intensive care resources.", {
  x: 0.5, y: 4.6, w: 9.0, h: 0.5,
  fontSize: 16, fontFace: "Arial", color: theme.primary, align: "center", italic: true
});
addBadge(s5, 5);

// ---------------------------------------------------------
// Slide 6: Treatment Gap
// ---------------------------------------------------------
const s6 = pres.addSlide();
s6.background = { color: theme.bg };
addSlideTitle(s6, "Treatment Is Available but Often Lacking or Poor Quality");

s6.addText("Mental illnesses are treatable and their impact can be reduced. Yet a profound gap persists between need and available care globally.", {
  x: 0.5, y: 1.3, w: 9.0, h: 0.6,
  fontSize: 16, fontFace: "Arial", color: theme.primary, bold: true
});

const gapPoints = [
  { icon: "🛑", title: "Stigma", text: "Discomfort disclosing symptoms to healthcare professionals or community members keeps many from seeking help." },
  { icon: "📉", title: "Access Barriers", text: "Treatment is often completely lacking, especially in low- and middle-income countries." },
  { icon: "🏥", title: "Quality of Care", text: "Even where treatment services exist, the quality of care provided may be inadequate." },
  { icon: "🙊", title: "Underreporting", text: "Due to stigma and lack of access, estimating true prevalence is difficult; actual burden is likely higher." }
];

gapPoints.forEach((pt, i) => {
  s6.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5 + (i % 2) * 4.6,
    y: 2.1 + Math.floor(i / 2) * 1.5,
    w: 4.4, h: 1.2,
    fill: { color: "FFFFFF" },
    line: { color: theme.light, width: 1 },
    rectRadius: 0.1
  });
  s6.addText(pt.icon, {
    x: 0.6 + (i % 2) * 4.6,
    y: 2.3 + Math.floor(i / 2) * 1.5,
    w: 0.6, h: 0.6,
    fontSize: 28, fontFace: "Arial", align: "center"
  });
  s6.addText(pt.title, {
    x: 1.3 + (i % 2) * 4.6,
    y: 2.2 + Math.floor(i / 2) * 1.5,
    w: 3.5, h: 0.4,
    fontSize: 18, fontFace: "Arial", color: theme.accent, bold: true
  });
  s6.addText(pt.text, {
    x: 1.3 + (i % 2) * 4.6,
    y: 2.6 + Math.floor(i / 2) * 1.5,
    w: 3.5, h: 0.6,
    fontSize: 14, fontFace: "Arial", color: theme.primary, valign: "top"
  });
});
addBadge(s6, 6);

// ---------------------------------------------------------
// Slide 7: Coping and Response
// ---------------------------------------------------------
const s7 = pres.addSlide();
s7.background = { color: theme.bg };
addSlideTitle(s7, "How People Cope: From Medication to Faith to Family Conversations");

s7.addText("Global survey data reveals wide variation in how people deal with anxiety or depression. Effective policy interventions must account for these cultural, economic, and systemic differences.", {
  x: 0.5, y: 1.3, w: 9.0, h: 0.8,
  fontSize: 16, fontFace: "Arial", color: theme.primary, align: "center"
});

// Category 1
s7.addShape(pres.shapes.ROUNDED_RECTANGLE, {
  x: 0.5, y: 2.3, w: 2.8, h: 2.2, fill: { color: theme.secondary }, rectRadius: 0.1
});
s7.addText("💊\n\nPrescribed Medication", {
  x: 0.5, y: 2.7, w: 2.8, h: 0.6,
  fontSize: 18, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center"
});
s7.addText("Common in higher-\nincome settings", {
  x: 0.5, y: 3.8, w: 2.8, h: 0.6,
  fontSize: 14, fontFace: "Arial", color: theme.light, align: "center"
});

// Category 2
s7.addShape(pres.shapes.ROUNDED_RECTANGLE, {
  x: 3.6, y: 2.3, w: 2.8, h: 2.2, fill: { color: theme.accent }, rectRadius: 0.1
});
s7.addText("🙏\n\nReligious & Spiritual", {
  x: 3.6, y: 2.7, w: 2.8, h: 0.6,
  fontSize: 18, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center"
});
s7.addText("Highly prevalent in\nmany regions worldwide", {
  x: 3.6, y: 3.8, w: 2.8, h: 0.6,
  fontSize: 14, fontFace: "Arial", color: "FFFFFF", align: "center"
});

// Category 3
s7.addShape(pres.shapes.ROUNDED_RECTANGLE, {
  x: 6.7, y: 2.3, w: 2.8, h: 2.2, fill: { color: theme.primary }, rectRadius: 0.1
});
s7.addText("🗣️\n\nTalking to Family/Friends", {
  x: 6.7, y: 2.7, w: 2.8, h: 0.6,
  fontSize: 18, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center"
});
s7.addText("A widely reported\ncoping mechanism", {
  x: 6.7, y: 3.8, w: 2.8, h: 0.6,
  fontSize: 14, fontFace: "Arial", color: theme.light, align: "center"
});
addBadge(s7, 7);

// ---------------------------------------------------------
// Slide 8: Key Takeaways
// ---------------------------------------------------------
const s8 = pres.addSlide();
s8.background = { color: theme.bg };
addSlideTitle(s8, "Key Takeaways: Prioritizing Care & Closing the Gap");

const bulletContent = [
  { text: "Depression and anxiety together", options: { bold: true } },
  { text: " represent the overwhelming majority of mental health DALYs (~80% of top 5 disorders).\n\n" },
  { text: "Schizophrenia and bipolar", options: { bold: true } },
  { text: " carry disproportionate individual burden and require specialized clinical care networks.\n\n" },
  { text: "Treatment exists", options: { bold: true } },
  { text: " but access and quality remain inadequate, especially in low- to middle-income areas.\n\n" },
  { text: "Stigma", options: { bold: true } },
  { text: " actively suppresses both help-seeking behavior and the collection of accurate prevalence data.\n\n" },
  { text: "Policy should prioritize", options: { bold: true } },
  { text: " scaling evidence-based interventions for common mental disorders while adapting to varied coping strategies and maintaining acute care structures." }
];

s8.addText(bulletContent, {
  x: 0.5, y: 1.5, w: 9.0, h: 3.5,
  fontSize: 18, fontFace: "Arial", color: theme.primary, bullet: true, valign: "top"
});
addBadge(s8, 8);

// ---------------------------------------------------------
// Save the file
// ---------------------------------------------------------
pres.writeFile({ fileName: '/app/output/final_deck.pptx' }).then(fileName => {
  console.log(`Created file: ${fileName}`);
}).catch(err => {
  console.error("Error creating PPTX: ", err);
});

